# Run this from inside your cloned Alert_project folder:
#   bash setup_project.sh
# It writes every project file into its correct location.
set -e
echo "Setting up AssetsAlert project files..."

mkdir -p ".github/workflows"
cat > ".github/workflows/build.yml" << 'FILEEOF'
name: Build APK

on:
  push:
    branches: [ main, master ]
  workflow_dispatch:

jobs:
  build:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Set up JDK 17
        uses: actions/setup-java@v4
        with:
          distribution: 'temurin'
          java-version: '17'

      # This project doesn't ship a gradlew wrapper (it was generated
      # offline, without network access to download gradle-wrapper.jar),
      # so we install Gradle directly instead of relying on ./gradlew.
      - name: Set up Gradle
        uses: gradle/actions/setup-gradle@v4
        with:
          gradle-version: 8.7

      - name: Build debug APK
        run: gradle assembleDebug --stacktrace

      - name: Upload APK
        uses: actions/upload-artifact@v4
        with:
          name: app-debug
          path: app/build/outputs/apk/debug/app-debug.apk
