</resources>
FILEEOF
echo "  wrote app/src/main/res/values/strings.xml"

mkdir -p "app/src/main/res/values"
cat > "app/src/main/res/values/themes.xml" << 'FILEEOF'
<?xml version="1.0" encoding="utf-8"?>
<resources>
    <style name="Theme.AssetsAlert" parent="android:Theme.Material.NoActionBar">
        <item name="android:statusBarColor">#121212</item>
        <item name="android:windowBackground">#121212</item>
    </style>

    <style name="Theme.AssetsAlert.Splash" parent="Theme.SplashScreen">
        <item name="windowSplashScreenBackground">@color/splash_background</item>
        <item name="windowSplashScreenAnimatedIcon">@drawable/splash_icon</item>
        <item name="windowSplashScreenIconBackgroundColor">@color/splash_background</item>
        <item name="postSplashScreenTheme">@style/Theme.AssetsAlert</item>
    </style>
</resources>
FILEEOF
echo "  wrote app/src/main/res/values/themes.xml"

cat > "build.gradle.kts" << 'FILEEOF'
plugins {
    id("com.android.application") version "8.5.2" apply false
    id("org.jetbrains.kotlin.android") version "1.9.24" apply false
    id("org.jetbrains.kotlin.plugin.compose") version "1.9.24" apply false
    id("com.google.devtools.ksp") version "1.9.24-1.0.20" apply false
}
FILEEOF
echo "  wrote build.gradle.kts"

cat > "gradle.properties" << 'FILEEOF'
org.gradle.jvmargs=-Xmx1280m -XX:MaxMetaspaceSize=384m -Dfile.encoding=UTF-8
android.useAndroidX=true
android.nonTransitiveRClass=true
kotlin.code.style=official

# --- Tuning for constrained on-device (tablet) builds ---
# Fewer parallel workers and no daemon retention avoids memory pressure
# building up across attempts, which is the most common cause of a
# build that silently hangs (rather than erroring) on mobile hardware.
org.gradle.daemon=false
org.gradle.parallel=false
org.gradle.workers.max=1
org.gradle.caching=true
org.gradle.configuration-cache=false

# Run the Kotlin compiler in-process instead of spawning a separate
# Kotlin daemon — one JVM instead of two competing for the same limited RAM.
kotlin.compiler.execution.strategy=in-process
kotlin.incremental=false
FILEEOF
echo "  wrote gradle.properties"

cat > "settings.gradle.kts" << 'FILEEOF'
pluginManagement {
    repositories {
        google()
        mavenCentral()
        gradlePluginPortal()
    }
}
dependencyResolutionManagement {
    repositoriesMode.set(RepositoriesMode.FAIL_ON_PROJECT_REPOS)
    repositories {
        google()
        mavenCentral()
    }
}

rootProject.name = "AssetsAlert"
include(":app")
FILEEOF
